        #region get options

        private void GetSportOptions(ref bool showSB, ref bool showHR, string sportOption)
        {
            //Get ShowSB, ShowHR
            switch (sportOption)
            {
                case "0": //Sport Book
                    showSB = true;
                    showHR = false;
                    break;

                case "151": //Horse Racing
                    showSB = false;
                    showHR = true;
                    break;

                default:
                    showSB = true;
                    showHR = true;
                    break;
            }
        }

        private void GetReportTypes(ref int reportType, string reportBy)
        {
            //Get Report Type (Daily/Monthly/Sport)
            switch (reportBy)
            {
                case "1": //Daily
                    reportType = 1;
                    break;

                case "2": //Monthly
                    reportType = 2;
                    break;

                case "3": //Sport
                    reportType = 3;
                    break;

                default:
                    reportType = 1;
                    break;
            }
        }

        private void GetCurrencyOptions(ref int baseCurrency, ref int custid, string currencyOption)
        {
            switch (currencyOption)
            {
                case "0": //default
                    baseCurrency = 0;
                    custid = 0;
                    break;

                case "-1":
                    baseCurrency = 3; //USD
                    custid = 0;
                    break;

                case "-2":
                    baseCurrency = 2; //RM
                    custid = 0;
                    break;

                default:
                    custid = CastAide.AsInt32(currencyOption);
                    baseCurrency = 0;
                    break;
            }
        }

        private string GetSportName(int id)
        {
            if (id == 0)
                return "Sportsbook";
            else if (id == 151)
                return "Horse Racing";
            else
                return string.Empty;
        }

